-- Adopt the phase staffing schema without replacing existing EdilCloud data.
-- SQLx executes this migration in a transaction under its migration lock.
DO $phase_staffing$
BEGIN
    IF to_regclass('projects_projectactivity') IS NULL
       OR to_regclass('projects_projecttask') IS NULL
       OR to_regclass('workspaces_profile') IS NULL THEN
        RAISE EXCEPTION 'Phase staffing requires the existing EdilCloud project schema';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid=to_regclass('projects_projectactivity')
          AND attname='inherit_workers' AND NOT attisdropped
    ) THEN
        ALTER TABLE projects_projectactivity
            ADD COLUMN inherit_workers boolean NOT NULL DEFAULT true;
        -- Existing explicitly staffed activities must retain their overrides.
        UPDATE projects_projectactivity a SET inherit_workers=false
        WHERE EXISTS (
            SELECT 1 FROM projects_projectactivity_workers aw
            WHERE aw.projectactivity_id=a.id
        );
        -- As in the Django migration, the application supplies the default.
        ALTER TABLE projects_projectactivity ALTER COLUMN inherit_workers DROP DEFAULT;
    END IF;

    IF to_regclass('projects_projecttask_workers') IS NULL THEN
        CREATE TABLE projects_projecttask_workers (
            id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            projecttask_id bigint NOT NULL,
            profile_id bigint NOT NULL,
            CONSTRAINT projects_phase_worker_unique UNIQUE (projecttask_id, profile_id),
            CONSTRAINT projects_phase_worker_task_fk FOREIGN KEY (projecttask_id)
                REFERENCES projects_projecttask(id) DEFERRABLE INITIALLY DEFERRED,
            CONSTRAINT projects_phase_worker_profile_fk FOREIGN KEY (profile_id)
                REFERENCES workspaces_profile(id) DEFERRABLE INITIALLY DEFERRED
        );
        CREATE INDEX projects_phase_worker_task_idx
            ON projects_projecttask_workers(projecttask_id);
        CREATE INDEX projects_phase_worker_profile_idx
            ON projects_projecttask_workers(profile_id);
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid=to_regclass('projects_projectactivity')
          AND attname='inherit_workers'
          AND (atttypid<>'boolean'::regtype OR NOT attnotnull)
    ) THEN
        RAISE EXCEPTION 'Existing activity inheritance column has an incompatible type';
    END IF;
END
$phase_staffing$;
